package com.causalops.demo;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@SpringBootApplication @RestController public class DemoApplication {static volatile int latency=0;public static void main(String[]x){SpringApplication.run(DemoApplication.class,x);}@PostMapping("/payments") Object pay(@RequestBody Map<String,Object>x)throws Exception{if(latency>0)Thread.sleep(latency);return Map.of("paymentId",UUID.randomUUID().toString(),"status","AUTHORIZED");}@PostMapping("/internal/fault") Object fault(@RequestBody Map<String,Object>x){latency=((Number)x.getOrDefault("latencyMs",0)).intValue();return Map.of("latencyMs",latency);}@GetMapping("/business") Object business()throws Exception{return Map.of("status","ready");}}
